import json

from google.adk.evaluation.eval_case import get_all_tool_calls

from agent_evals import cases


def test_checked_in_evalset_and_config_match_the_code():
    """evals/*.json is generated by `python -m agent_evals.cases`; editing one without the other fails here."""
    assert cases.EVALSET_PATH.read_text() == cases.evalset_json()
    assert cases.CONFIG_PATH.read_text() == cases.config_json()


def test_evalset_is_valid_and_has_unique_ids():
    eval_set = cases.build_eval_set()
    ids = [c.eval_id for c in eval_set.eval_cases]
    assert len(ids) == len(set(ids)) >= 5
    assert json.loads(cases.config_json())["criteria"] == cases.CRITERIA


def test_set_covers_tool_use_and_no_tool_cases():
    counts = [len(get_all_tool_calls(c.conversation[0].intermediate_data)) for c in cases.build_eval_set().eval_cases]
    assert max(counts) == 1 and counts.count(0) >= 2  # conversions call the tool; refusals/clarifications must not


def test_reference_conversions_are_correct():
    """The expected answers are checked against zoneinfo, so a typo in the eval set cannot pass silently."""
    import datetime
    from zoneinfo import ZoneInfo

    for eval_id, _, tools, answer in cases.CASES:
        for call in tools:
            a = call["args"]
            hh, mm = map(int, a["time"].split(":"))
            src = datetime.datetime(2026, 1, 15, hh, mm, tzinfo=ZoneInfo(a["source_timezone"]))
            for month in (1, 7):  # no daylight saving in these zones: same answer in both seasons
                moved = src.replace(month=month).astimezone(ZoneInfo(a["target_timezone"]))
                assert moved.strftime("%H:%M") in answer, eval_id
